function validate([color]) {
  if (typeof color !== 'string' || color.length !== 7) return 'color has exactly 7 characters.';
  if (color[0] !== '#') return 'color starts with #.';
  if (!/^[0-9a-f]{6}$/.test(color.slice(1))) return 'After # come six lowercase hex digits (0-9, a-f).';
  return null;
}

