function similarRGB(color) {
  const hexDigits = '0123456789abcdef';
  const channels = [1, 3, 5].map(i => parseInt(color.substr(i, 2), 16));
  let best = null;
  let bestScore = -Infinity;
  for (const r of hexDigits) for (const g of hexDigits) for (const b of hexDigits) {
    const candidate = [r, g, b].map(d => parseInt(d + d, 16));
    let score = 0;
    for (let c = 0; c < 3; c++) score -= (candidate[c] - channels[c]) ** 2;
    if (score > bestScore) { bestScore = score; best = '#' + r + r + g + g + b + b; }
  }
  return best;
}

