function generate(rand, size) {
  const hexDigits = '0123456789abcdef';
  let color = '#';
  for (let i = 0; i < 6; i++) {
    // Small inputs lean towards the edges and the middle of the hex range now and then.
    const edge = size === 'small' && rand() < 0.2;
    color += edge ? '0f78'[Math.floor(rand() * 4)] : hexDigits[Math.floor(rand() * 16)];
  }
  return [color];
}
